import java.util.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import com.koios.game.arpg.*;import com.koios.game.model.*;import com.koios.game.model.item.*;
public final class ConstructProfileCheck {
 static int checks;static void check(boolean b,String label){checks++;if(!b)throw new AssertionError(label);}
 public static void main(String[]args)throws Exception{PrototypeIntegrationCheck.loaded();StringBuilder report=new StringBuilder("# Furnace Sentinel construct gameplay contract\n\nDedicated ID15001/template90, one tile conditional on native mesh bounds<128. Existing attack5487 and death5491 preserved. Death duration6ticks. No extra AOE. Attack5487 starts one tick before conditional physical impact; leaving reach or line of sight avoids it. Cadence7ticks gives4.2seconds between strikes, versus3seconds for previous sentinel. Initial actor stagger3..5ticks unchanged.\n\n|Tier|ConstructHP|Old sentinelHP|Hit|Old hit|Raw DPS|Old DPS|Starter mail incoming DPS|Reference killsec|\n|---:|---:|---:|---:|---:|---:|---:|---:|---:|\n");
 EncounterProfiles.Profile construct=EncounterProfiles.get(1,15001),old=EncounterProfiles.get(1);check(construct!=old&&construct.id.equals("furnace_construct"),"Foundry sentinel selects bounded override");EncounterProfiles.Profile briar=EncounterProfiles.get(1,15007);check(briar.health(1,false)==old.health(1,false)&&briar.damage(1)==old.damage(1)&&briar.attackTicks==old.attackTicks&&EncounterProfiles.get(1,90)==old,"Courtyard statistics and vanilla sentinel retain baseline");check(briar.attackAnimation==5487&&briar.windupTicks==1,"Briar uses verified configured swing and windup");check(EncounterProfiles.get(0,15001)==EncounterProfiles.get(0),"Wrong role cannot inherit construct override");for(int tier:new int[]{1,3,6}){int level=tier*2;EquipmentBases.Base weapon=EquipmentBases.starter(true);for(EquipmentBases.Base b:EquipmentBases.all())if(level>=4&&b.itemId==22430)weapon=b;Map<Stat,Double> stats=ArpgStats.equipment(new Item[]{EquipmentBases.create(weapon,level),EquipmentBases.create(EquipmentBases.starter(false),level)},level);double dps=(stats.get(Stat.PHYSICAL_MIN)+stats.get(Stat.PHYSICAL_MAX))/2*stats.get(Stat.ATTACK_SPEED)*(1+stats.get(Stat.CRITICAL_CHANCE)/100*(stats.get(Stat.CRITICAL_MULTIPLIER)/100-1))*Defences.hitChance(stats.get(Stat.ACCURACY),4*tier);double raw=construct.damage(tier)/(.6*construct.attackTicks),baseline=old.damage(tier)/(.6*old.attackTicks);check(raw<=baseline*1.08,"Heavy hit cadence avoids large rawDPS increase");check(construct.health(tier,false)<=old.health(tier,false)*1.37,"Durability remains bounded");double incoming=Defences.mitigate(construct.damage(tier),DamageType.PHYSICAL,stats,false)/(.6*construct.attackTicks)*Defences.hitChance(100+(20+tier*5)*10,stats.get(Stat.EVASION));report.append(String.format(Locale.ROOT,"|%d|%d|%d|%d|%d|%.3f|%.3f|%.3f|%.2f|%n",tier,construct.health(tier,false),old.health(tier,false),construct.damage(tier),old.damage(tier),raw,baseline,incoming,construct.health(tier,false)/dps));}
 try(CombatPresentationCheck.Fixture f=new CombatPresentationCheck.Fixture()){MapRuns.MapMob dummy=f.mob(f.area(6,4,0),false);dummy.setDead(true);MapRuns.MapMob mob=f.mob(f.area(6,4,1),false);check(mob.getId()==15001&&mob.getSize()==1&&!mob.elite,"Actual Foundry construct has isolated ID and one-tile normal actor");check(mob.getMaxHitpoints()==41,"Actual constructor applies variant HP");f.stand(CombatPresentationCheck.offset(mob.getLocation(),2,0));double before=CombatPresentationCheck.pool(f.p);f.run.ticks=mob.nextAttackTick-1;MapRuns.tick(f.p);check(CombatPresentationCheck.pool(f.p)==before&&mob.strikeAt==f.run.ticks+1,"Heavy animation starts one tick before damage");check(mob.nextAttackTick==f.run.ticks+7,"Actual construct attack uses seven-tick interval");check(mob.getCurrentAnimation().getId()==5487,"Actual construct requests agreed attack sequence");int next=mob.nextAttackTick;MapRuns.tick(f.p);check(before-CombatPresentationCheck.pool(f.p)==3&&mob.strikeAt==0&&mob.nextAttackTick==next,"Heavy impact follows next tick without adding an extra cooldown tick");mob.hurt(999999,f.p);check(mob.getCurrentAnimation().getId()==5491&&mob.collapseTicks()==6,"Construct death remains verified skeleton-rig collapse");}
 String original=System.getProperty("arpg.enemies.path");String json=new String(Files.readAllBytes(Paths.get(original==null?"data/arpg/enemies.json":original)),StandardCharsets.UTF_8);java.lang.reflect.Field cached=EncounterProfiles.class.getDeclaredField("profiles");cached.setAccessible(true);Path probe=Files.createTempFile(Paths.get("build"),"encounter-profile-validation-",".json");try{com.google.gson.JsonArray seven=new com.google.gson.JsonParser().parse(json).getAsJsonArray();while(seven.size()>7)seven.remove(seven.size()-1);Files.write(probe,seven.toString().getBytes(StandardCharsets.UTF_8));System.setProperty("arpg.enemies.path",probe.toString());cached.set(null,null);check(EncounterProfiles.get(1,15001).health(1,false)==30,"Existing seven-role data remains compatible without overrides");for(int invalid=0;invalid<3;invalid++){com.google.gson.JsonArray data=new com.google.gson.JsonParser().parse(json).getAsJsonArray();if(invalid==0)data.add(data.get(7));if(invalid==1)data.get(7).getAsJsonObject().addProperty("role",5);if(invalid==2)data.get(7).getAsJsonObject().addProperty("npcId",15012);Files.write(probe,data.toString().getBytes(StandardCharsets.UTF_8));cached.set(null,null);boolean rejected=false;try{EncounterProfiles.get(1,15001);}catch(IllegalStateException expected){rejected=true;}check(rejected,"Malformed/duplicate/role-mismatched override rejected atomically "+invalid);}}finally{if(original==null)System.clearProperty("arpg.enemies.path");else System.setProperty("arpg.enemies.path",original);cached.set(null,null);Files.deleteIfExists(probe);}
 Files.write(Paths.get("../../logs/construct-balance.md"),report.toString().getBytes(StandardCharsets.UTF_8));System.out.println("Passed "+checks+" staged construct identity/balance/cadence checks.");}
}
